import{_ as e,o as l,c as i,ak as r}from"./chunks/framework.BHDkgpnK.js";const g=JSON.parse('{"title":"KossJS 版本变更日志（dev.5 → dev.8）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/version/changelog-dev.5-to-dev.8.md","filePath":"zh/version/changelog-dev.5-to-dev.8.md","lastUpdated":1782310918000}'),s={name:"zh/version/changelog-dev.5-to-dev.8.md"};function d(a,t,o,n,c,_){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="kossjs-版本变更日志-dev-5-→-dev-8" tabindex="-1">KossJS 版本变更日志（dev.5 → dev.8） <a class="header-anchor" href="#kossjs-版本变更日志-dev-5-→-dev-8" aria-label="Permalink to “KossJS 版本变更日志（dev.5 → dev.8）”">​</a></h1><p>本文档记录从 0.1.0-dev.5 到 0.1.0-dev.8 的所有变更。</p><hr><h2 id="_0-1-0-dev-5-→-0-1-0-dev-6" tabindex="-1">0.1.0-dev.5 → 0.1.0-dev.6 <a class="header-anchor" href="#_0-1-0-dev-5-→-0-1-0-dev-6" aria-label="Permalink to “0.1.0-dev.5 → 0.1.0-dev.6”">​</a></h2><h3 id="新增功能" tabindex="-1">新增功能 <a class="header-anchor" href="#新增功能" aria-label="Permalink to “新增功能”">​</a></h3><ul><li><strong>Senri FFI 子系统</strong>：JS 调用 native C 库的完整 FFI <ul><li>_senri_ffi.open：加载动态库</li><li>_senri_ffi.func：调用 C 函数</li><li>_senri_ffi.alloc：内存分配/释放</li><li>_senri_ffi.callback：创建 JS 回调指针</li><li>_senri_ffi.struct：结构体、数组、指针操作</li><li>_senri_ffi.types：FFI 类型定义</li></ul></li><li><strong>N-API 兼容层</strong>：支持加载 .node 原生插件 <ul><li>process.dlopen：动态库加载</li><li>N-API 函数注册、对象操作、字符串处理</li></ul></li><li><strong>Buffer 全局对象</strong>：Node.js 兼容的 Buffer 实现</li><li><strong>GPL 许可证输出</strong>：所有公共 C API 入口输出许可证信息</li><li><strong>事件循环扩展</strong>：支持异步 FFI 回调和任务管理</li><li><strong>CI 改进</strong>：增加 workflow_dispatch、autotools、ARM64 MSVC 支持</li></ul><h3 id="移除" tabindex="-1">移除 <a class="header-anchor" href="#移除" aria-label="Permalink to “移除”">​</a></h3><ul><li>移除旧的纯 JS fetch 实现</li></ul><hr><h2 id="_0-1-0-dev-6-→-0-1-0-dev-7" tabindex="-1">0.1.0-dev.6 → 0.1.0-dev.7 <a class="header-anchor" href="#_0-1-0-dev-6-→-0-1-0-dev-7" aria-label="Permalink to “0.1.0-dev.6 → 0.1.0-dev.7”">​</a></h2><h3 id="新增功能-1" tabindex="-1">新增功能 <a class="header-anchor" href="#新增功能-1" aria-label="Permalink to “新增功能”">​</a></h3><ul><li><strong>28 位细粒度能力位系统</strong>：替代旧的 5 位粗粒度系统 <ul><li>文件系统（6 个）：FS_READ, FS_WRITE, FS_DELETE, FS_MKDIR, FS_RENAME, FS_CHMOD</li><li>网络（5 个）：NET_TCP_CLIENT, NET_TCP_SERVER, NET_UDP, NET_DNS, NET_FETCH</li><li>加密（4 个）：CRYPTO_HASH, CRYPTO_HMAC, CRYPTO_RANDOM, CRYPTO_PBKDF2</li><li>FFI（5 个）：FFI_OPEN, FFI_CALL, FFI_ALLOC, FFI_CALLBACK, FFI_STRUCT</li><li>其他（8 个）：NATIVE_ADDON, WASM, SHARED_MEMORY, HIGHRES_TIME, SYSINFO, MODULE_LOAD, DYNAMIC_CODE, DEBUG_CAP</li></ul></li><li><strong>沙箱安全三层机制</strong>： <ul><li>能力位掩码（Capability Bitmask）：静态权限声明</li><li>审核掩码（Audit Mask）：动态审核策略</li><li>审核回调（Audit Callback）：运行时动态决策</li></ul></li><li><strong>审核掩码 API</strong>： <ul><li>koss_set_audit_mask：设置审核掩码</li><li>koss_get_audit_mask：获取当前审核掩码</li></ul></li><li><strong>审核回调 API</strong>： <ul><li>koss_check_sandbox：注册/清除同步审核回调</li></ul></li><li><strong>审核调试模式</strong>： <ul><li>koss_enable_audit_debug：启用/禁用调试模式</li><li>错误消息优化：区分能力错误（KossCapabilityError）和审核错误（KossSecurityError）</li></ul></li><li><strong>FFI 沙箱测试</strong>：15 个 FFI 能力位测试</li><li><strong>综合沙箱测试</strong>：81 个沙箱安全测试</li><li><strong>KossJS 全局对象</strong>：自动获取版本号、运行时信息和 stable 模式状态（<code>version</code>、<code>runtime</code>、<code>isStable</code>）</li></ul><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to “修复”">​</a></h3><ul><li><strong>跨平台编译修复</strong>： <ul><li>iOS/Android/鸿蒙：gate FFI/libloading 依赖</li><li>Linux aarch64：统一 c_char 类型</li><li>OHOS：排除 ohos target 的 libffi/libloading 依赖</li><li>非桌面平台：stub 函数签名修复</li></ul></li><li><strong>内存管理修复</strong>： <ul><li>回调 buffer 生命周期统一由 Rust 侧管理</li><li>移除 Python 侧手动 free 回调 buffer 的逻辑</li></ul></li><li><strong>沙箱审核回调修复</strong>：ctypes 兼容性问题</li><li><strong>跨平台 CI 修复</strong>： <ul><li>Ubuntu：KossInstance 结构体字段 drop 顺序问题</li><li>macOS：dylib 文件名不匹配</li><li>Windows：临时目录路径问题</li></ul></li></ul><h3 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to “变更”">​</a></h3><ul><li>移除 runtime.rs 中重复的能力位常量，统一使用 sandbox 模块</li><li>is_capability_enabled 使用新的 28 位复合常量</li></ul><hr><h2 id="_0-1-0-dev-7-→-0-1-0-dev-8" tabindex="-1">0.1.0-dev.7 → 0.1.0-dev.8 <a class="header-anchor" href="#_0-1-0-dev-7-→-0-1-0-dev-8" aria-label="Permalink to “0.1.0-dev.7 → 0.1.0-dev.8”">​</a></h2><h3 id="新增功能-2" tabindex="-1">新增功能 <a class="header-anchor" href="#新增功能-2" aria-label="Permalink to “新增功能”">​</a></h3><ul><li><strong>stable 模式</strong>：控制实例的生产就绪模式 <ul><li>stable 参数（默认 true）：禁用 FFI 和 Worker 等不稳定功能</li><li>koss_is_stable() C ABI 函数：查询实例是否处于稳定模式</li><li>stable=True 时自动剥离 FFI 和 Worker 能力位</li><li>stable=True 且 caps 包含 FFI/Worker 时，注册 stub 函数（调用时抛出明确错误）</li><li>stable=True 时 equire(&#39;worker_threads&#39;) 被模块加载器拦截</li><li>C ABI 6 个 worker 函数添加 stable 感知错误消息</li><li>Worker 类错误消息提示设置 stable=false</li></ul></li><li><strong>TypeScript 接口封装</strong>：kossjs_interface.ts <ul><li>基于 koffi 的完整封装</li><li>支持所有 C ABI 函数</li><li>支持能力位控制、审核掩码、审核回调、稳定模式</li></ul></li><li><strong>Python 接口新增</strong>： <ul><li>get_capabilities()：查询当前能力位掩码</li><li>is_stable 属性：查询实例是否处于稳定模式</li></ul></li><li><strong>C 头文件新增</strong>： <ul><li>koss_is_stable() 函数声明</li><li>旧 koss_create/koss_create_with_modules 改为 static inline 向后兼容</li></ul></li><li><strong>worker_threads 模块能力位</strong>：从 DYNAMIC_CODE 改为 KOSS_CAP_WORKER</li><li><strong>Node.js 内置库简化重构</strong>（提交 d481465，2026-06-23）： <ul><li>移除 Node.js 官方源码依赖，替换为自定义精简实现</li><li>移除对 <code>internalBinding()</code>、<code>primordials</code> 等 Node.js 内部 API 的依赖</li><li>代码量减少约 10 万行</li></ul></li><li><strong>zlib 压缩支持</strong>：添加 <code>flate2</code> Rust crate 依赖 <ul><li><code>gzip()</code> / <code>gzipSync()</code>、<code>gunzip()</code> / <code>gunzipSync()</code></li><li><code>deflate()</code> / <code>deflateSync()</code>、<code>inflate()</code> / <code>inflateSync()</code></li><li><code>constants</code>：zlib 常量定义</li></ul></li><li><strong>TCP Socket 持久化</strong>：在 <code>runtime.rs</code> 中实现 TCP 连接持久化管理</li></ul><h3 id="重构" tabindex="-1">重构 <a class="header-anchor" href="#重构" aria-label="Permalink to “重构”">​</a></h3><ul><li><strong>内置库实现变更</strong>：</li></ul><table tabindex="0"><thead><tr><th>模块</th><th>实现方式</th><th>支持 API</th></tr></thead><tbody><tr><td><strong>crypto</strong></td><td>自定义 JS + <code>__koss_hash</code>/<code>__koss_random_bytes</code>/<code>__koss_random_uuid</code></td><td>randomBytes, createHash(sha256/sha1/md5), randomUUID, timingSafeEqual, randomFill, randomFillSync, getHashes</td></tr><tr><td><strong>net</strong></td><td>自定义 JS + <code>__koss_tcp_*</code></td><td>Socket, Server, connect(), createServer(), isIP(), isIPv4(), isIPv6()</td></tr><tr><td><strong>http</strong></td><td>自定义 JS</td><td>createServer(), IncomingMessage, ServerResponse, METHODS, STATUS_CODES（仅服务端）</td></tr><tr><td><strong>https</strong></td><td>基于 http + net 封装</td><td>createServer(), request(), get()（无实际 TLS）</td></tr><tr><td><strong>stream</strong></td><td>自定义 JS</td><td>Readable, Writable, Duplex, Transform, PassThrough, pipeline(), finished()</td></tr><tr><td><strong>zlib</strong></td><td>自定义 JS + <code>__koss_gzip*</code>（flate2）</td><td>gzip/gunzip, deflate/inflate（sync + async）, constants</td></tr><tr><td><strong>dgram</strong></td><td>自定义 JS（基于 TCP 桥接）</td><td>createSocket(), socket.bind/send/close/address()</td></tr><tr><td><strong>tls</strong></td><td>基于 net 模块轻量封装</td><td>connect(), createServer(), TLSSocket（无实际加密）</td></tr><tr><td><strong>dns</strong></td><td>自定义 JS + <code>__koss_dns_lookup</code></td><td>lookup(), resolve(), resolve4(), resolve6(), promises.lookup()</td></tr><tr><td><strong>util</strong></td><td>自定义 JS</td><td>format(), inspect(), deprecate(), promisify(), callbackify(), inherits(), debuglog(), types.*</td></tr><tr><td><strong>diagnostics_channel</strong></td><td>自定义 JS</td><td>channel(), subscribe(), unsubscribe(), publish(), hasSubscribers()</td></tr><tr><td><strong>perf_hooks</strong></td><td>自定义 JS</td><td>performance(now/mark/measure), PerformanceObserver, createHistogram(), timerify()</td></tr><tr><td><strong>trace_events</strong></td><td>自定义 JS</td><td>createTracing(), getEnabledCategories(), Tracing class</td></tr></tbody></table><h3 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to “测试”">​</a></h3><ul><li>新增 test_stable_mode.py：11 个稳定模式测试</li><li>新增 7 个内置库测试文件：test_crypto, test_diagnostics_channel, test_net, test_perf_hooks, test_trace_events, test_util, test_zlib_dgram</li><li>更新现有测试：FFI/Worker 相关测试添加 stable=False</li><li>测试统计：528 passed, 8 skipped</li></ul><h3 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to “文档”">​</a></h3><ul><li>新增 TypeScript 接口使用文档</li><li>更新安全与沙箱指南、API 概览、版本管理规范、快速开始、Python 接口文档</li><li>新增 API 文档：koss_is_stable, koss_set_audit_mask, koss_get_audit_mask, koss_check_sandbox, koss_enable_audit_debug</li><li>新增 Node.js 内置库支持状态表</li></ul><h3 id="移除-1" tabindex="-1">移除 <a class="header-anchor" href="#移除-1" aria-label="Permalink to “移除”">​</a></h3><ul><li>删除过时的设计实现步骤文档</li><li>移除 Node.js 官方源码的复杂实现（约 10 万行代码）</li><li>移除 zlib 模块中的 Brotli、Zstd 压缩支持（保留 gzip/deflate）</li><li>移除 util 模块中的 getCallSites()、parseArgs() 等高级功能</li><li>移除 stream 模块中的 compose()、addAbortSignal() 等未实现功能</li></ul><h3 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to “已知限制”">​</a></h3><ul><li><code>http</code> 模块仅支持服务端，客户端未实现</li><li><code>https</code>/<code>tls</code> 模块无实际 TLS 加密</li><li><code>dgram</code> 模块基于 TCP 桥接，非真实 UDP</li><li><code>zlib</code> 模块的异步函数实际为同步实现</li><li><code>stream</code> 模块的 promises.pipeline/finished 返回 rejected promises</li><li><code>perf_hooks</code> 模块的 monitorEventLoopDelay() 为 stub</li></ul><hr><h2 id="统计" tabindex="-1">统计 <a class="header-anchor" href="#统计" aria-label="Permalink to “统计”">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>新增文件</th><th>修改文件</th><th>新增测试</th></tr></thead><tbody><tr><td>dev.5 → dev.6</td><td>~10</td><td>~20</td><td>~50</td></tr><tr><td>dev.6 → dev.7</td><td>~15</td><td>~30</td><td>~100</td></tr><tr><td>dev.7 → dev.8</td><td>~12</td><td>~45</td><td>~130</td></tr><tr><td><strong>总计</strong></td><td><strong>~37</strong></td><td><strong>~95</strong></td><td><strong>~280</strong></td></tr></tbody></table>',34)])])}const u=e(s,[["render",d]]);export{g as __pageData,u as default};
